const output = [];

for (const item of items) {
  const input = item.json.body && typeof item.json.body === 'object' ? item.json.body : item.json;
  const productId = String(input.product_id || '').trim();
  if (!/^[a-z0-9][a-z0-9_-]*$/i.test(productId)) {
    throw new Error('product_id is required and may contain only letters, numbers, underscores, and hyphens.');
  }

  const githubUrl = String(input.github_url || '').trim();
  if (!githubUrl) throw new Error('github_url is required. Upload the matching product first.');

  const rawBlocks = Array.isArray(input.prompt_blocks)
    ? input.prompt_blocks
    : String(input.prompt_text || input.prompt_blocks || '').split(/\r?\n\s*={3,}\s*\r?\n/);
  const promptBlocks = rawBlocks.map(value => String(value || '').trim()).filter(Boolean);
  if (!promptBlocks.length) {
    throw new Error('No prompt blocks were supplied. Put at least one non-empty prompt in the matching .txt file.');
  }

  const uploadedImages = Array.isArray(input.uploaded_images) ? input.uploaded_images : [];
  const imageReferences = uploadedImages
    .map(image => typeof image === 'string' ? image : (image.cdn_url || image.raw_url || image.github_url || image.url || ''))
    .map(String)
    .map(value => value.trim())
    .filter(value => /^https?:\/\//i.test(value));

  if (!imageReferences.length) {
    throw new Error('No public uploaded_images URLs were returned by the product upload workflow. Do not submit a manual prompt until product images are uploaded.');
  }

  const runId = `manual_${productId}_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  promptBlocks.forEach((promptText, index) => {
    output.push({
      json: {
        product_id: productId,
        github_url: githubUrl,
        branch: String(input.branch || 'main'),
        product_folder: String(input.product_folder || `products/${productId}`),
        source_prompt_file: String(input.source_prompt_file || ''),
        prompt_index: index + 1,
        prompt_count: promptBlocks.length,
        promptText,
        promptImage: imageReferences[0],
        image_references: imageReferences,
        uploaded_images: uploadedImages,
        duration: String(input.duration || '10'),
        ratio: String(input.ratio || '9:16'),
        dry_run: input.dry_run === true || String(input.dry_run).toLowerCase() === 'true',
        manual_run_id: runId
      }
    });
  });
}

return output;

return items.map(item => ({
  json: {
    ...item.json,
    moyin_create_response: {
      id: `dryrun_${item.json.manual_run_id}_${item.json.prompt_index}`,
      status: 'queued',
      object: 'video',
      dry_run: true
    },
    moyin_full_url: 'dry-run://videos'
  }
}));

const https = require('https');
const { URL } = require('url');

function joinUrl(base, path) {
  return `${String(base || '').replace(/\/+$/, '')}/${String(path || '').replace(/^\/+/, '')}`;
}

function requestJson(urlString, apiKey, body) {
  return new Promise((resolve, reject) => {
    const url = new URL(urlString);
    const encoded = JSON.stringify(body);
    const request = https.request({
      hostname: url.hostname,
      port: url.port || 443,
      path: url.pathname + url.search,
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(encoded)
      },
      timeout: Number($env.MOYIN_CREATE_TIMEOUT_SECONDS || 180) * 1000
    }, response => {
      let raw = '';
      response.on('data', chunk => { raw += chunk.toString(); });
      response.on('end', () => {
        let parsed = raw;
        try { parsed = JSON.parse(raw); } catch (error) {}
        resolve({ statusCode: response.statusCode || 0, body: parsed, raw });
      });
    });
    request.on('timeout', () => request.destroy(new Error('Moyin create request timed out')));
    request.on('error', reject);
    request.write(encoded);
    request.end();
  });
}

const baseUrl = String($env.MOYIN_API_BASE_URL || '').trim();
const apiKey = String($env.MOYIN_API_KEY || '').trim();
if (!baseUrl) throw new Error('MOYIN_API_BASE_URL is required for manual video submission.');
if (!apiKey) throw new Error('MOYIN_API_KEY is required for manual video submission.');

const output = [];
for (const item of items) {
  const j = item.json;
  const fullUrl = joinUrl(baseUrl, '/videos');
  const requestBody = {
    model: String($env.MOYIN_VIDEO_MODEL || 'omni-fast'),
    prompt: j.promptText,
    images: Array.isArray(j.image_references) ? j.image_references : [j.promptImage].filter(Boolean),
    aspect_ratio: j.ratio || '9:16',
    aspectRatio: j.ratio || '9:16',
    seconds: String(j.duration || '10'),
    resolution: String($env.MOYIN_VIDEO_RESOLUTION || '720p')
  };
  const response = await requestJson(fullUrl, apiKey, requestBody);
  if (response.statusCode < 200 || response.statusCode >= 300) {
    throw new Error(`Moyin create failed HTTP ${response.statusCode}; full_url=${fullUrl}; response=${response.raw}`);
  }
  output.push({ json: { ...j, moyin_create_response: response.body, moyin_full_url: fullUrl, moyin_request_body: requestBody } });
}
return output;

function readPath(value, path) {
  return path.split('.').reduce((current, key) => current == null ? undefined : current[key], value);
}

function extractTaskId(response) {
  const paths = ['id', 'taskId', 'task_id', 'data.id', 'data.task_id', 'data.taskId', 'result.id', 'result.task_id', 'result.taskId'];
  for (const candidate of paths) {
    const value = readPath(response, candidate);
    if (value !== undefined && value !== null && String(value).trim()) return String(value);
  }
  return '';
}

const jobsRoot = String($env.N8N_LOCAL_JOBS_DIR || 'E:/n8n-video-gemini/video_jobs').replace(/\\/g, '/').replace(/\/+$/, '');
const outputRoot = String($env.N8N_LOCAL_OUTPUT_DIR || 'E:/n8n-video-gemini/video_output').replace(/\\/g, '/').replace(/\/+$/, '');
const baseUrl = String($env.MOYIN_API_BASE_URL || '').replace(/\/+$/, '');
const output = [];

for (const item of items) {
  const j = item.json;
  const taskId = extractTaskId(j.moyin_create_response || {});
  if (!taskId) {
    throw new Error(`Moyin response did not contain task id. full_url=${j.moyin_full_url || ''}; response=${JSON.stringify(j.moyin_create_response || {})}`);
  }
  const jobId = `job_${j.product_id}_${Date.now()}_${String(j.prompt_index).padStart(2, '0')}`;
  const statusDir = `${jobsRoot}/${jobId}`;
  const outputDir = `${outputRoot}/${j.product_id}/${jobId}`;
  const scene = {
    scene_id: 'video_001',
    moyin_task_id: taskId,
    promptImage: j.promptImage,
    promptText: j.promptText,
    duration: String(j.duration || '10'),
    ratio: String(j.ratio || '9:16'),
    output_file: `${outputDir}/video_001.mp4`
  };
  const jobPayload = {
    job_id: jobId,
    script_id: `manual_${j.product_id}_${String(j.prompt_index).padStart(2, '0')}`,
    product_id: j.product_id,
    active_skill: 'manual_prompt',
    github_url: j.github_url,
    product_folder: j.product_folder,
    skill_path: '',
    source_prompt_file: j.source_prompt_file,
    prompt_index: j.prompt_index,
    prompt_count: j.prompt_count,
    output_dir: outputDir,
    status_dir: statusDir,
    max_runtime_seconds: Number($env.MOYIN_TIMEOUT_SECONDS || 900),
    poll_interval_seconds: Number($env.MOYIN_POLL_INTERVAL_SECONDS || 8),
    moyin_api: {
      base_url: baseUrl,
      query_path_template: '/videos/{task_id}',
      status_paths: ['status', 'state', 'taskStatus', 'data.status', 'data.state', 'result.status', 'result.state'],
      video_url_paths: ['video_url', 'videoUrl', 'result.video_url', 'result.videoUrl', 'result.resultUrls.0', 'data.video_url', 'data.videoUrl', 'data.resultUrls.0', 'url', 'output_url', 'outputUrl'],
      success_statuses: ['completed', 'succeeded', 'success', 'done', 'finished'],
      failed_statuses: ['failed', 'error', 'cancelled', 'canceled']
    },
    scenes: [scene]
  };
  const jobJsonString = JSON.stringify(jobPayload, null, 2);
  output.push({
    json: {
      ...j,
      job_id: jobId,
      script_id: jobPayload.script_id,
      job_payload: jobPayload,
      job_json_string: jobJsonString,
      job_file_path: `${jobsRoot}/inbox/${jobId}.json`,
      status_file: `${statusDir}/status.json`,
      output_dir: outputDir,
      worker_log: `${statusDir}/worker.log`
    },
    binary: {
      data: { data: Buffer.from(jobJsonString, 'utf8').toString('base64'), mimeType: 'application/json', fileName: `${jobId}.json` }
    }
  });
}
return output;

const fs = require('fs');
const path = require('path');

for (const item of items) {
  const j = item.json;
  const target = String(j.job_file_path || '').replace(/\\/g, '/');
  if (!target || !/\/inbox\/[^/]+\.json$/i.test(target)) {
    throw new Error(`Unsafe manual job_file_path: ${target}`);
  }
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, String(j.job_json_string || ''), 'utf8');
  j.job_file_written = true;
}
return items;

return [{
  json: {
    ok: true,
    status: 'submitted',
    dry_run: Boolean(items[0] && items[0].json.dry_run),
    product_id: items[0] ? items[0].json.product_id : '',
    source_prompt_file: items[0] ? items[0].json.source_prompt_file : '',
    submitted_jobs: items.map(item => ({
      job_id: item.json.job_id,
      script_id: item.json.script_id,
      prompt_index: item.json.prompt_index,
      prompt_count: item.json.prompt_count,
      scene_id: 'video_001',
      job_file: item.json.job_file_path,
      status_file: item.json.status_file,
      output_dir: item.json.output_dir,
      worker_log: item.json.worker_log
    })),
    message: 'Manual prompt jobs submitted. Each prompt block creates exactly one video_001 task.'
  }
}];
